                cursor.next += 1;
                continue;
            }
            *target
        };
        let color = colors
            .get(target)
            .ok_or_else(|| replay_error(function, "exact census movement has an unknown target"))?;
        match color {
            0 => {
                if frontier.len() == frontier.capacity() {
                    return Err(replay_error(
                        function,
                        "exact census frontier exceeds node count",
                    ));
